    // const addMore = (index) => {
    //     const clone = { ...mainForms }
    //     clone.commision_list[index].slots.push({ start_amt: '', end_amt: '', charge: '', charge_type: '', commision: '', commision_type: '', distributor_comm: '', distributor_comm_type: '', master_distributer_com: '' })
