import { useEffect, useState } from "react";
import {  Row, Col, Modal, Tabs, Card, message, Layout, Typography,Tag , Select , Button ,  Checkbox, Input} from "antd";
import { 
  UserOutlined, 
  BankOutlined, 
  IdcardOutlined, 
  FileTextOutlined, 
  CheckCircleOutlined, 
  AppstoreOutlined, 
  SafetyCertificateOutlined 
} from "@ant-design/icons";
import kycVid from "../../assets/images/kyc/kycVideo.png";
import { ToastContainer,toast } from "react-toastify";
import { useParams } from "react-router-dom";
import { getCourierSingleUser , approveunapproveCourierUser } from "../../api/login/Login";
import CustomInputField from "../../common/CustomInputField";
