import KycModals from "../../components/distributer/createUserDistributer/kycDetails/kycModals/KycModals";
const { Title } = Typography;
const { Content } = Layout;
const { Option } = Select;


const DocumentDetails = ({initialValues})=> {
  const [videoModalOpen, setVideoModalOpen] = useState(false);
  const [previewModal, setPreviewModal] = useState({
    visible: false,
    image: null,
    title: ''
  });

  const handlePreview = (url, title) => {
    setPreviewModal({
      visible: true,
      image: url,
      title
    });
  };

  const imageTitles = {
    adhaarImgFront: 'Aadhaar Card Front',
    adhaarImgBack: 'Aadhaar Card Back',
    bankImg: 'Bank Document',
    panImg: 'PAN Card',
    shopFront: 'Shop Front',
    shopInnerImg: 'Shop Inner Image',
    shopLeftOfOuter: 'Left Outer View',
    shopRightOfOuter: 'Right Outer View',
    shopOuterImg: 'Shop Outer View',
    shopNearByImage: 'Nearby Shop Area',
  };

  const kycVideoSrc = initialValues?.kycVideo || initialValues?.kyc_video || initialValues?.docs?.kycVideo || initialValues?.docs?.kyc_video;

  const getThumbnailVideoUrl = (path) => {
    if (!path || typeof path !== 'string') return '';
    if (path.startsWith('http://') || path.startsWith('https://')) return path;
    return `${baseUrVideos}${path}`;
  };

  return (
    <>
     <div className="p-4">
          <Card className="shadow-sm">
            <h3 className="mb-4 ">KYC Documentation</h3>
   <Row gutter={[24, 24]}>
          
              {Object?.entries(imageTitles)?.map(([key, title]) => (
     <Col xs={24} sm={12} lg={8} xl={6} key={key}>

   
      <DocumentCard
        title={title}
        imageSrc={
          initialValues?.[key] ? `${baseUrlImage}${initialValues[key]}` : null
        }
        dummyImage=""
        onClick={() => handlePreview(initialValues?.[key], title)}
      />
    </Col>
  ))}
   <Col xs={24} sm={12} lg={8} xl={6}>
            <Card className="h-100 shadow-sm" bodyStyle={{ padding: '12px' }}>
              <div className="text-center mb-3">
                <h5 className="fw-bold text-primary p-2 bg-light rounded">KYC Video</h5>
              </div>
              <div 
                className="position-relative cursor-pointer" 
                style={{ height: '200px', overflow: 'hidden' }}
                onClick={() => setVideoModalOpen(true)}
              >
                
                {kycVideoSrc ? (
                  <>
                    <video 
                      src={getThumbnailVideoUrl(kycVideoSrc)}
                      className="w-100 h-100 object-fit-cover"
                    />
                    <div className="position-absolute top-50 start-50 translate-middle">
                      <div className="play-btn"></div>
                    </div>
                  </>
                ) : (
                  <div className="h-100 d-flex flex-column justify-content-center align-items-center bg-light">
                    <img src={kycVid} alt="Video placeholder" className="mb-2" style={{ width: '64px' }} />
                    <p className="text-muted mb-0"><small>KYC Video Not Found</small></p>
                  </div>
                )}
              </div>
            </Card>
          </Col>

   <Col xs={24} sm={12} lg={8} xl={6}>
            <Card className="h-100 shadow-sm" bodyStyle={{ padding: '12px' }}>
              <div className="text-center mb-3">
                <h5 className="fw-bold text-primary p-2 bg-light rounded">Location Details</h5>
              </div>
              <div className="p-3">
                {initialValues?.longitude ? (
                  <>
                    <p className="mb-2">
                      <strong>Longitude: </strong>
                      {initialValues.longitude}
                    </p>
                    <p className="mb-0">
                      <strong>Latitude: </strong>
                      {initialValues.latitude}
                    </p>
                  </>
                ) : (
                  <p className="text-muted text-center mb-0">Location Not Found</p>
                )}
              </div>
            </Card>
          </Col>
            </Row>
            </Card>
            </div>

  
  <Modal
        open={previewModal.visible}
        visible={previewModal.visible}
        title={previewModal.title}
        footer={null}
        onCancel={() => setPreviewModal({ visible: false, image: null, title: '' })}
        width={800}
        centered
      >
        {previewModal.image && (
          <img
            src={`${baseUrlImage}${previewModal.image}`}
            alt={previewModal.title}
            style={{ width: '100%', height: 'auto' }}
          />
        )}
      </Modal>
      <KycModals 
        open={videoModalOpen}
        setOpen={setVideoModalOpen}
        kycVideo={kycVideoSrc || "KYC Videos Not Found"}
      />
    </>
  )
}




