const  ApprovedArea = ({setResetKey , retailerInfo}) => {
   
  const params = useParams();
  const id = params?.id;
   const [checkBoxDisable, setCheckboxDisable] = useState(false);

  const [formData, setFormData] = useState({
    is_courierOnboarding: false,
    is_courierDoc: false,
    is_courierVideo: false,
    is_courierSingup: false,
    
    remark: "",
  });

  const handleApprovalChange = (value) => {
    if (value === true) {
      setCheckboxDisable(true);
      setFormData({
        ...formData,
        is_courierOnboarding: true,
        is_courierDoc: true,
        is_courierVideo: true,
        is_courierSingup: true,
      
        remark: "",
      });
    } else {
      setCheckboxDisable(false);
      setFormData({
        ...formData,
        is_courierOnboarding: false,
        remark: "",
      });
    }
  };

  const handleCheckboxChange = (key) => {
    setFormData((prev) => ({
      ...prev,
      [key]: !prev[key],
    }));
  };

  const handleRemarkChange = (e) => {
    setFormData({ ...formData, remark: e.target.value });
  };

  const handleSubmit = async (action) => {
    try {
      const res = await approveunapproveCourierUser(formData, retailerInfo?._id); // Replace with actual API call
      if (res?.error === false) {
        message.success(res.message || `${action} action successful!`);
        setResetKey((pre)=>!pre)
      } else {
        message.error(res.message || `${action} action failed!`);
      }
    } catch (error) {
      console.error("Submission error:", error);
      message.error("An error occurred during submission.");
    }
  };

  const allChecked = Object.keys(formData)
    .filter((key) => key.startsWith("is_courier"))
    .every((key) => formData[key] === true);

  const atLeastOneUnchecked = Object.keys(formData)
    .filter((key) => key.startsWith("is_courier"))
    .some((key) => formData[key] === false);

  const isApproveButtonEnabled = formData.is_courierOnboarding === true && allChecked;
  const isUnapproveButtonEnabled =
    formData.is_courierOnboarding === false &&
    atLeastOneUnchecked &&
    formData.remark.trim().length > 0;

  useEffect(() => {
    if (retailerInfo?.is_courierOnboarding === true) {
      setCheckboxDisable(true);
    }
    setFormData((prev) => ({
      ...prev,
      is_courierOnboarding: retailerInfo?.is_courierOnboarding || false,
      is_courierDoc: retailerInfo?.is_courierDoc || false,
      is_courierVideo: retailerInfo?.is_courierVideo || false,
      is_courierSingup: retailerInfo?.is_courierSingup || false,
      remark: "",
    }));
  }, [retailerInfo]);

  return (
    <div className="approved-area">
      <h3>Courier Approval</h3>
      <Select
        style={{ width: "100%", marginBottom: "1rem" }}
        onChange={handleApprovalChange}
        value={formData?.is_courierOnboarding}
      >
        <Option disabled value="">Select Approval Status</Option>
        <Option value={true}>Approved</Option>
        <Option value={false}>Not Approved</Option>
      </Select>

      <div>
        {/* <Checkbox
          checked={formData.is_courierOnboarding}
          onChange={() => handleCheckboxChange("is_courierOnboarding")}
          disabled={checkBoxDisable}
        >
          Courier Onboarding
        </Checkbox> */}
        <Checkbox
          checked={formData.is_courierDoc}
          onChange={() => handleCheckboxChange("is_courierDoc")}
          disabled={checkBoxDisable}
        >
          Courier Document
        </Checkbox>
        <Checkbox
          checked={formData.is_courierVideo}
          onChange={() => handleCheckboxChange("is_courierVideo")}
          disabled={checkBoxDisable}
        >
          Courier Video
        </Checkbox>
        <Checkbox
          checked={formData.is_courierSingup}
          onChange={() => handleCheckboxChange("is_courierSingup")}
          disabled={checkBoxDisable}
        >
          Courier Signup
        </Checkbox>
        {/* <Checkbox
          checked={formData.is_courierAgreement}
          onChange={() => handleCheckboxChange("is_courierAgreement")}
          disabled={checkBoxDisable}
        >
          Courier Agreement
        </Checkbox> */}
      </div>

      {formData.is_courierOnboarding === false && (
        <Input
          placeholder="Enter Remark"
          value={formData.remark}
          onChange={handleRemarkChange}
          style={{ marginTop: "1rem" }}
        />
      )}

      <div style={{ marginTop: "1rem" }}>
        <Button
          onClick={() => handleSubmit("Approve")}
          disabled={!isApproveButtonEnabled}
          style={{ marginRight: "1rem" }}
        >
          Approve
        </Button>
        <Button
          onClick={() => handleSubmit("Unapprove")}
          disabled={!isUnapproveButtonEnabled}
        >
          Unapprove
        </Button>
      </div>
    </div>
  )
}

const CourierOnboardingUserVerify = () => {
  
  const [userDetails , setUserDetails] = useState('')
  const  { id }=  useParams()
  const [resetKey , setResetKey] = useState(false)


      const getUser = async()=>{
       
          let res = await getCourierSingleUser(id)
          console.log(res  , "res")
          if(res?.error === false)
          {
            setUserDetails(res?.data)
          }
      }


  useEffect(()=>{
    getUser()
  },[resetKey])

  const bankDetails = [
    { label: "Bank Name", value: userDetails?.bankDetails?.bank_name || '' },
    { label: "Account Number", value: userDetails?.bankDetails?.bank_account_number || '' },
    { label: "IFSC Code", value: userDetails?.bankDetails?.bank_ifsc || '' },
    { label: "Account Holder Name", value: userDetails?.bankDetails?.bank_account_name || '' },
  ]


  const items = [
    {
      key: "SponserDetails",
      label: (
        <span className="tab-label">
          <IdcardOutlined /> Sponsor Details
        </span>
      ),
      children: (
        <div className="tab-content">
           <div className="row">
  {userDetails?.sponsor && Object.keys(userDetails.sponsor).length > 0 ? (
    Object.keys(userDetails.sponsor).map((item, index) => (
      <div className="col-xl-4 mb-3" key={index}>
        <CustomInputField
          type="text"
          placeholder={item.charAt(0).toUpperCase() + item.slice(1)}
          value={userDetails.sponsor[item]}
          id={item}
          name={item}
        />
      </div>
    ))
  ) : (
    <div className="col-12">
      <p>User Signup without sponsor</p>
    </div>
  )}
</div>

        </div>
      ),
    },
    {
      key: "RegistrationDetails",
      label: (
        <span className="tab-label">
           <UserOutlined /> Registration Details
        </span>
      ),
      children: (
        <div className="tab-content">
           <SignUp initialValues={userDetails} />
        </div>
      ),
    },
    {
      key: "BankDetails",
      label: (
        <span className="tab-label">
           <BankOutlined /> Bank Details
        </span>
      ),
      children: (
        <div className="tab-content">
           {/* <SignUp initialValues={userDetails} /> */}
           <div className="p-4">
          <Card className="shadow-sm">
            <h3 className="mb-4 ">Bank Details</h3>
   <Row gutter={[24, 24]}>
   {bankDetails?.map(({ label, value }, index) => (
   <Col xs={24} sm={12} lg={12} xl={8}>
  
   <CustomInputField
          type="text"
          placeholder={label}
          value={value || ''}
          id={label}
          name={label}
        />
   </Col>
     ))}
   </Row>
   </Card>
   </div>
        </div>
      ),
    },
    {
      key: "DocumentDetails",
      label: (
        <span className="tab-label">
          <SafetyCertificateOutlined /> Document Details
        </span>
      ),
      children: (
        <div className="tab-content">
           <DocumentDetails initialValues={userDetails} />
        </div>
      ),
    },
 
    // {
    //   key: "AgreementDetails",
    //   label: (
    //     <span className="tab-label">
    //       <IdcardOutlined /> Agreement Details
    //     </span>
    //   ),
    //   children: (
    //     <div className="tab-content">
        
    //     </div>
    //   ),
    // },
 
  
 
  
   
    {
      key: "Approval",
      label: (
        <span className="tab-label">
          <CheckCircleOutlined /> Approval
        </span>
      ),
      children: (
        <div className="tab-content">
          <ApprovedArea setResetKey={setResetKey} retailerInfo ={userDetails?.users}/>
        </div>
      ),
    },
  
  ];
  return (
   <>
    <Layout className="main-layout">
      <Content>
        <div className="page-header">
          <Title level={4} className="page-title">
           Courier User Details
          </Title>
          <Tag 
            color={userDetails?.users?.is_courierOnboarding ? '#52c41a' : '#faad14'} 
            className="status-badge"
          >
            {userDetails?.users?.is_courierOnboarding ? 'Approved' : 'Pending'}
          </Tag>
        </div>

        <Card className="main-card">
          <Tabs
            defaultActiveKey="IdentifyVerification"
            items={items}
            destroyInactiveTabPane={true}
            animated={{
              tabPane: true,
            }}
            className="custom-tabs"
          />
        </Card>
      </Content>
      <ToastContainer />
    </Layout>
   
   </>
  )
}

export default CourierOnboardingUserVerify